SELECT * FROM (SELECT CASE WHEN unit_price >= 310 THEN 'high' WHEN unit_price >= 60 THEN 'mid' ELSE 'low' END AS unit_price_bucket, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(*) AS order_item_count FROM order_items GROUP BY CASE WHEN unit_price >= 310 THEN 'high' WHEN unit_price >= 60 THEN 'mid' ELSE 'low' END, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END) AS sub WHERE order_item_count < 5 ORDER BY order_item_count, unit_price_bucket, quantity_bucket LIMIT 10;
